package com.example.springbootjwtcrud.controller;import com.example.springbootjwtcrud.exception.ExpensesException;import com.example.springbootjwtcrud.model.ExpensesCategories;import com.example.springbootjwtcrud.service.ExpenseService;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.List;import java.util.Map;@RestController@RequestMapping(("/expenses"))public class ExpensesController {    private final ExpenseService expenseService;    public ExpensesController(ExpenseService expenseService) {        this.expenseService = expenseService;    }    @GetMapping("/totalExpense")    public ResponseEntity<Map<String, Object>> GetTotalExpenses(){        List<Double> totalExpenseResult = expenseService.GetAllExpenses();        if(totalExpenseResult.isEmpty()){            return new ResponseEntity<>(HttpStatus.NO_CONTENT);        }        return ResponseEntity.ok(                Map.of("status" , "success pare",                        "totalExpense", totalExpenseResult)        );    }    @DeleteMapping("/removeExpense/{amount}")    public ResponseEntity<Object> DeleteExpense(@PathVariable("amount") Double amount){        String deleteResult = expenseService.DeleteExpense(amount);        return ResponseEntity.ok(                Map.of("Message: ", deleteResult)        );    }    @PostMapping("/listExpense/{amount}/{category}")    public ResponseEntity<Object> ListExpense(@PathVariable("amount") Double amount, @PathVariable("category") ExpensesCategories expensesCategories){        String listExpenseResult = expenseService.ListExpense(amount, expensesCategories);        return ResponseEntity.ok(                Map.of("Message: ", listExpenseResult)        );    }    @PutMapping("/updateExpense/{amount}/{newAmount}")    public ResponseEntity<Object> UpdateExpense(@PathVariable("amount") Double amount, @PathVariable("newAmount") Double newAmount){        String updateExpenseResult = expenseService.UpdateExpensePrice(amount, newAmount);        return ResponseEntity.ok(                Map.of("Message: ", updateExpenseResult)        );    }}